																				"htmlContent": "<input id=\"onLoadRFQStatus\" type=\"hidden\" style=\"display:none;\" onclick=\"SetStatus(event);\">\n<div id=\"RFQStatus\" class=\"text-size-M\"><span></span></div>\n<script type=\"text/javascript\">\n\twindow.postMessage({ eventName: \"onLoadRFQStatus\", control: \"RFQStatusTag__\" }, document.location.origin);\n\tfunction SetStatus(evt)\n\t{\n\t\tvar RFQStatusContainer = document.getElementById(\"RFQStatus\");\n\n\t\tvar statusClass = \"text-color-\" + evt.color;\n\n\t\tRFQStatusContainer.querySelector('span').innerHTML =  evt.statusLabel;\n\t\tRFQStatusContainer.classList.add(statusClass);\n\t}\n\n\tfunction OnClick()\n\t{\n\t\twindow.postMessage({ eventName: \"onClick\", control: \"RFQStatusTag__\"}, document.location.origin);\n\t}\n</script>",
