																						"css": "@ .comparison-table-container {\n\t--comparator-border-color: #d7d9db;\n\n\tmargin-right: 15px;\n\tmargin-top: 25px;\n\n\t.comparison-table {\n\t\twidth: 100%;\n\t\tborder-collapse: collapse;\n\t\tcontain: paint;\n\t\ttable-layout: fixed;\n\t\tmin-width: calc(300px + 180px * attr(data-nb-vendors type(<integer>)));\n\n\t\tthead {\n\t\t\tth {\n\t\t\t\tpadding: 20px 10px;\n\t\t\t\tbackground-color: white;\n\n\t\t\t\t&.item-column {\n\t\t\t\t\tmax-width: 280px;\n\t\t\t\t\twidth: 280px;\n\t\t\t\t}\n\n\t\t\t\t&.vendor-column {\n\t\t\t\t\tborder-top: 1px solid var(--comparator-border-color);\n\t\t\t\t\tborder-right: 1px solid var(--comparator-border-color);\n\t\t\t\t\tborder-left: 1px solid var(--comparator-border-color);\n\t\t\t\t\tdiv.vendor-header-detailed {\n\t\t\t\t\t\tdisplay: flex;\n\t\t\t\t\t\tflex-direction: column;\n\t\t\t\t\t\tgap: 4px;\n\t\t\t\t\t\tjustify-content: center;\n\t\t\t\t\t\talign-items: center;\n\t\t\t\t\t\twidth: fit-content;\n\t\t\t\t\t\tmax-width: 100%;\n\t\t\t\t\t\tmargin: auto;\n\n\t\t\t\t\t\tdiv {\n\t\t\t\t\t\t\tdisplay: flex;\n\t\t\t\t\t\t\tgap: 3px;\n\t\t\t\t\t\t\talign-items: center;\n\t\t\t\t\t\t\tmax-width: 100%;\n\t\t\t\t\t\t\tcolor: var(--text-color-color5);\n\n\t\t\t\t\t\t\t&.vendor-main-info {\n\t\t\t\t\t\t\t\tfont-size: 20px;\n\t\t\t\t\t\t\t\tline-height: 25px;\n\t\t\t\t\t\t\t\tfont-family: \"Roboto Bold\", sans-serif;\n\n\t\t\t\t\t\t\t\t.vendor-score {\n\t\t\t\t\t\t\t\t\tfloat: none;\n\t\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\t\t.vendor-name {\n\t\t\t\t\t\t\t\t\toverflow: hidden;\n\t\t\t\t\t\t\t\t\ttext-overflow: ellipsis;\n\t\t\t\t\t\t\t\t\tmax-width: 100%;\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\ti.material-symbols-rounded {\n\t\t\t\t\t\t\t\tfont-size: 15px;\n\t\t\t\t\t\t\t}\n\n\t\t\t\t\t\t\tspan {\n\t\t\t\t\t\t\t\tfont-weight: normal;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\ttbody {\n\t\t\tborder-right: 1px solid var(--comparator-border-color);\n\t\t\tborder-left: 1px solid var(--comparator-border-color);\n\t\t\tborder-bottom: 1px solid var(--comparator-border-color);\n\n\t\t\ttr.section-title-row {\n\t\t\t\tbackground-color: var(--table-header-cell-background-color, var(--otherlist-header-background-color));\n\t\t\t\tcolor: var(--element-text-secondary-color, white);\n\t\t\t\tborder-right: 1px solid var(--comparator-border-color);\n\t\t\t\tborder-left: 1px solid var(--comparator-border-color);\n\t\t\t\ttd.section-title {\n\t\t\t\t\tpadding: 2px 0px;\n\t\t\t\t\tspan.section-title-content {\n\t\t\t\t\t\ttext-transform: uppercase;\n\t\t\t\t\t\tpadding-left: 5px;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\n\t\t\ttr.questionnaire-header-row ~ tr.questionnaire-header-row,\n\t\t\ttr.item-header-row ~ tr.item-header-row {\n\t\t\t\tborder-top: 3px solid var(--comparator-border-color);\n\t\t\t}\n\n\t\t\ttr.questionnaire-header-row,\n\t\t\ttr.item-header-row {\n\t\t\t\ttd {\n\t\t\t\t\t&.section-label-header,\n\t\t\t\t\t&.item-name-header {\n\t\t\t\t\t\tpadding-left: 15px;\n\t\t\t\t\t\tpadding-top: 5px;\n\t\t\t\t\t\tpadding-bottom: 5px;\n\n\t\t\t\t\t\t.item-main-name {\n\t\t\t\t\t\t\tcolor: var(--text-color-color5);\n\t\t\t\t\t\t\tfont-size: 14px;\n\t\t\t\t\t\t\tline-height: 21px;\n\t\t\t\t\t\t\toverflow: hidden;\n\t\t\t\t\t\t\ttext-overflow: ellipsis;\n\t\t\t\t\t\t\tfont-family: \"Roboto Bold\", sans-serif;\n\t\t\t\t\t\t\tdisplay: block;\n\t\t\t\t\t\t\tdisplay: -webkit-box;\n\t\t\t\t\t\t\t-webkit-line-clamp: 2;\n\t\t\t\t\t\t\t-webkit-box-orient: vertical;\n\t\t\t\t\t\t\twhite-space: normal;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\n\t\t\t\t.tag-container {\n\t\t\t\t\tmin-height: 24px;\n\t\t\t\t\ttext-align: center;\n\t\t\t\t}\n\t\t\t}\n\n\t\t\ttr.questionnaire-row,\n\t\t\ttr.item-info-row {\n\t\t\t\t&.even-row {\n\t\t\t\t\tbackground-color: var(--main-color-grey-less-light);\n\t\t\t\t}\n\n\t\t\t\ttd {\n\t\t\t\t\tpadding: 5px 10px;\n\n\t\t\t\t\t.item-main-name {\n\t\t\t\t\t\tmin-height: 24px;\n\t\t\t\t\t}\n\n\t\t\t\t\t&.question-title,\n\t\t\t\t\t&.line-title,\n\t\t\t\t\t&.info-label {\n\t\t\t\t\t\tcolor: var(--text-color-color1);\n\t\t\t\t\t\tfont-family: \"Roboto Bold\", sans-serif;\n\t\t\t\t\t\ttext-align: right;\n\t\t\t\t\t\tpadding-right: 10px;\n\t\t\t\t\t\toverflow: hidden;\n\t\t\t\t\t\ttext-overflow: ellipsis;\n\t\t\t\t\t\tdisplay: block;\n\t\t\t\t\t\tdisplay: -webkit-box;\n\t\t\t\t\t\t-webkit-line-clamp: 4;\n\t\t\t\t\t\t-webkit-box-orient: vertical;\n\t\t\t\t\t\twhite-space: normal;\n\t\t\t\t\t\tline-height: 20px;\n\t\t\t\t\t}\n\n\t\t\t\t\t&.vendor-cell {\n\t\t\t\t\t\ttext-align: center;\n\t\t\t\t\t\tcolor: var(--text-color-color5);\n\n\t\t\t\t\t\t.best-value {\n\t\t\t\t\t\t\tfont-family: \"Roboto Bold\", sans-serif;\n\t\t\t\t\t\t}\n\n\t\t\t\t\t\t.question-answer,\n\t\t\t\t\t\t.item-comment {\n\t\t\t\t\t\t\toverflow: hidden;\n\t\t\t\t\t\t\ttext-overflow: ellipsis;\n\t\t\t\t\t\t\tdisplay: block;\n\t\t\t\t\t\t\tdisplay: -webkit-box;\n\t\t\t\t\t\t\t-webkit-line-clamp: 4;\n\t\t\t\t\t\t\t-webkit-box-orient: vertical;\n\t\t\t\t\t\t\twhite-space: pre-wrap;\n\t\t\t\t\t\t\ttext-align: center;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\n\t\t\ttr.documents-info-row {\n\t\t\t\t&:nth-child(even) {\n\t\t\t\t\tbackground-color: var(--main-color-grey-less-light);\n\t\t\t\t}\n\n\t\t\t\ttd {\n\t\t\t\t\tborder-right: 1px solid var(--comparator-border-color);\n\t\t\t\t\tborder-left: 1px solid var(--comparator-border-color);\n\t\t\t\t\tpadding: 5px 10px;\n\n\t\t\t\t\t&.info-label {\n\t\t\t\t\t\tcolor: var(--text-color-color1);\n\t\t\t\t\t\tfont-family: \"Roboto Bold\", sans-serif;\n\t\t\t\t\t\ttext-align: right;\n\t\t\t\t\t\tpadding-right: 10px;\n\t\t\t\t\t}\n\n\t\t\t\t\t&.vendor-cell {\n\t\t\t\t\t\ttext-align: center;\n\n\t\t\t\t\t\ta {\n\t\t\t\t\t\t\ttext-decoration: underline;\n\t\t\t\t\t\t\tcolor: var(--text-color-color5);\n\t\t\t\t\t\t\ttext-overflow: ellipsis;\n\t\t\t\t\t\t\toverflow: hidden;\n\t\t\t\t\t\t\tdisplay: block;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\n\t\t\ttr {\n\t\t\t\ttd.vendor-cell,\n\t\t\t\ttd.vendor-header-cell {\n\t\t\t\t\tborder-right: 1px solid var(--comparator-border-color);\n\t\t\t\t\tborder-left: 1px solid var(--comparator-border-color);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n}\n",
																						"htmlContent": "<input id=\"onLoaded\" type=\"hidden\" onclick=\"registerEvent()\">\n<input id=\"onHTMLChange\" type=\"hidden\" onclick=\"onHTMLChange(event)\">\n<div id=\"comparison-table-container\" class=\"comparison-table-container\">\n</div>\n<script>\n\tfunction registerEvent()\n\t{\n\t\tconst closestScrollableParent = document.getElementById(\"comparison-table-container\").closest(\".splitter-container.scrollable-y\");\n\t\tclosestScrollableParent.addEventListener(\"scroll\", onScroll);\n\t}\n\n\tfunction onScroll()\n\t{\n\t\ttry\n\t\t{\n\t\t\tconst comparisonTableContainer = document.getElementById(\"comparison-table-container\");\n\t\t\tconst splitterContainer = comparisonTableContainer.closest(\".splitter-container\");\n\t\t\tconst containerTop = splitterContainer.getBoundingClientRect().top;\n\t\t\tconst table = comparisonTableContainer.querySelector(\"#comparison-table\");\n\t\t\tconst tablebbox = table.getBoundingClientRect();\n\t\t\tconst isVisible = (tablebbox.bottom - containerTop) > 0;\n\t\t\tlet translateY = isVisible ? -tablebbox.top + containerTop : 0;\n\t\t\tconst tHead = table.tHead;\n\t\t\tconst headerLine = tHead && tHead.querySelector(\"tr\");\n\t\t\tif (headerLine)\n\t\t\t{\n\t\t\t\tconst columns = headerLine.querySelectorAll(\"th\");\n\t\t\t\tfor (const column of columns)\n\t\t\t\t{\n\t\t\t\t\tcolumn.style.transform = \"translateY(\" + Math.max(0, translateY).toString() + \"px)\";\n\t\t\t\t}\n\t\t\t\tconst sections = table.querySelectorAll(\".section-title-row\");\n\t\t\t\tconst headerBox = headerLine.getBoundingClientRect();\n\t\t\t\tfor (let i = 0; i < sections.length; i++)\n\t\t\t\t{\n\t\t\t\t\tconst section = sections[i];\n\t\t\t\t\tsection.style.transform = \"translateY(0px)\"; //reset translateY to correctly calculate section bounding box\n\t\t\t\t\tconst sectionbbox = section.getBoundingClientRect();\n\t\t\t\t\tconst bottomOfSectionElement = sections[i + 1] || table;\n\t\t\t\t\tconst bottomOfSection = bottomOfSectionElement.getBoundingClientRect().bottom;\n\t\t\t\t\tconst isVisible = (bottomOfSection - containerTop - headerBox.height) > 0;\n\t\t\t\t\ttranslateY = isVisible ? -sectionbbox.top + containerTop + headerBox.height : 0;\n\t\t\t\t\tsection.style.transform = \"translateY(\" + Math.max(0, translateY).toString() + \"px)\";\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tcatch(e)\n\t\t{\n\t\t\tdebugger;\n\t\t}\n\t}\n\n\tfunction onHTMLChange(evt)\n\t{\n\t\tconst comparisonTableContainer = document.getElementById(\"comparison-table-container\");\n\t\tcomparisonTableContainer.innerHTML = evt.newTable;\n\t}\n</script>"
